const out = [];
for (let p = 1; p <= 30; p++) { out.push({ json: { page: p } }); }
return out;

const res = $input.all();
let total = null; let pageCount = null; let fetched = 0; const statuses = [];
const prefixKeys = []; const refs = []; const sameText = [];
function nm(k) { const n = k.key_name || {}; return n.web || n.other || n.ios || n.android || JSON.stringify(n); }
function tr(k) { const o = {}; for (const t of (k.translations || [])) { o[t.language_iso] = t.translation; } return o; }
for (const r of res) {
  const j = r.json || {}; statuses.push(j.statusCode);
  const h = j.headers || {};
  if (h['x-pagination-total-count']) { total = h['x-pagination-total-count']; pageCount = h['x-pagination-page-count']; }
  const keys = (j.body && j.body.keys) || [];
  fetched += keys.length;
  for (const k of keys) {
    const name = nm(k); const t = tr(k);
    const base = { key_id: k.key_id, name: name, archived: k.is_archived, is_plural: k.is_plural, tags: k.tags, description: k.description, translations: t };
    if (name.toLowerCase().indexOf('learnabout') >= 0) { prefixKeys.push(base); continue; }
    let isRef = false;
    for (const iso in t) { const v = String(t[iso] || ''); if (/\[%key:[^%]*learnabout/i.test(v)) { isRef = true; } }
    if (isRef) { refs.push(base); continue; }
    for (const iso in t) { const v = String(t[iso] || ''); if (/aprender sobre/i.test(v) || /^\s*learn about\s*$/i.test(v)) { sameText.push(base); break; } }
  }
}
return [{ json: { total: total, pageCount: pageCount, fetched: fetched, statuses: statuses.filter(function(s){return s!==200;}), prefixKeys: prefixKeys, refs: refs, sameText: sameText } }];
